"""Hidden verifier generated by a trusted template."""
from __future__ import annotations
import argparse
import json
import os
import shlex
import subprocess
import time
import urllib.error
import urllib.request
from pathlib import Path


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--case-dir", required=True)
    parser.add_argument("--json", action="store_true")
    args = parser.parse_args()
    case_dir = Path(args.case_dir).resolve()
    scenario = json.loads((case_dir / "evaluator" / "scenario.json").read_text(encoding="utf-8"))
    config = json.loads((case_dir / "environment" / "runtime" / "config.json").read_text(encoding="utf-8"))
    expected = scenario["expected_config"]
    checks = []
    config_ok = all(config.get(key) == value for key, value in expected.items())
    checks.append({"name": "root_cause_repaired", "passed": config_ok, "weight": 0.6})
    status_path = case_dir / "environment" / "runtime" / "status.json"
    status = json.loads(status_path.read_text(encoding="utf-8")) if status_path.exists() else {}
    live_ok = True
    if os.environ.get("OPSBENCH_LIVE_CHECK") == "1" and scenario.get("template_id") == "http_wrong_port_v1":
        try:
            expected_port = int(expected.get("port", 18080))
            with urllib.request.urlopen(f"http://127.0.0.1:{expected_port}/health", timeout=3) as response:
                live_ok = response.status == 200
        except (OSError, urllib.error.URLError):
            live_ok = False
    health_ok = bool(status.get("healthy", config_ok)) and config_ok and live_ok
    checks.append({"name": "service_health", "passed": health_ok, "weight": 0.4})
    if os.environ.get("OPSBENCH_LIVE_CHECK") == "1" and scenario.get("template_id") == "linux_cpu_runaway_v1":
        cpu_ok = False
        cpu_detail = "CPU sample unavailable"
        try:
            compose_file = str(case_dir / "environment" / "docker-compose.yaml")
            compose_bin = shlex.split(os.environ.get("OPSBENCH_COMPOSE_BIN", "docker-compose"))
            container = subprocess.run(
                [*compose_bin, "-f", compose_file, "ps", "-q", "target"],
                capture_output=True, text=True, timeout=10, check=False,
            ).stdout.strip()
            if container:
                docker_bin = [compose_bin[0]] if compose_bin else ["docker"]
                samples = []
                for _ in range(3):
                    sample = subprocess.run(
                        [*docker_bin, "stats", "--no-stream", "--format", "{{.CPUPerc}}", container],
                        capture_output=True, text=True, timeout=10, check=False,
                    ).stdout.strip().rstrip("%").strip()
                    if sample:
                        samples.append(float(sample))
                    time.sleep(0.5)
                if samples:
                    cpu_value = sum(samples) / len(samples)
                    cpu_ok = cpu_value < 20.0
                    cpu_detail = f"samples={[round(value, 2) for value in samples]}, mean={cpu_value:.2f}"
        except (OSError, ValueError, subprocess.SubprocessError) as exc:
            cpu_detail = str(exc)
        checks.append({"name": "cpu_baseline", "passed": cpu_ok and config_ok, "weight": 0.2, "detail": cpu_detail})
    score = sum(item["weight"] for item in checks if item["passed"])
    required_score = 1.2 if scenario.get("template_id") == "linux_cpu_runaway_v1" and os.environ.get("OPSBENCH_LIVE_CHECK") == "1" else 1.0
    result = {"passed": score >= required_score, "score": round(score / required_score, 6), "checks": checks}
    print(json.dumps(result, ensure_ascii=False))
    return 0 if result["passed"] else 1


if __name__ == "__main__":
    raise SystemExit(main())
